WITH ranked AS (SELECT * FROM store_sales QUALIFY ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY units DESC, id) = 1) SELECT CASE WHEN revenue >= 3800 THEN 'PREMIUM' ELSE 'STANDARD' END AS revenue_tier, store_id, CASE WHEN units >= 39 THEN 'LARGE' ELSE 'SMALL' END AS units_tier, BIT_OR(units) AS units_bit_or, MAX(revenue) AS max_revenue, CORR(units, revenue) AS corr_units_revenue, BIT_AND(units) AS units_bit_and, PERCENTILE_APPROX(units, 0.95) AS units_p95 FROM ranked GROUP BY CASE WHEN revenue >= 3800 THEN 'PREMIUM' ELSE 'STANDARD' END, store_id, CASE WHEN units >= 39 THEN 'LARGE' ELSE 'SMALL' END;
